SELECT "Hatred_1"."Keyword" AS "Keyword",   "Hatred_1"."State_" AS "State_",   SUM(1) AS "TEMP_Calculation_327707273997602816__2109769841__0_",   CAST(MAX("Hatred_1"."StatePopNum") AS BIGINT) AS "TEMP_Calculation_327707273997602816__3451088709__0_",   CAST(MIN("Hatred_1"."StatePopNum") AS BIGINT) AS "TEMP_Calculation_327707273997602816__3855970114__0_" FROM "Hatred_1" WHERE (("Hatred_1"."Keyword" IN ('camel jockey', 'dyke', 'japs', 'jungle bunnies', 'kike', 'lesbo', 'man in a dress', 'men in dresses', 'midget', 'mongoloid', 'porch monkey', 'twat', 'wetback', 'whitey', 'yid')) OR (("Hatred_1"."Keyword" >= 'beaner') AND ("Hatred_1"."Keyword" <= 'bimbo')) OR (("Hatred_1"."Keyword" >= 'chauvinist pig') AND ("Hatred_1"."Keyword" <= 'cripple')) OR (("Hatred_1"."Keyword" >= 'dindu') AND ("Hatred_1"."Keyword" <= 'dothead')) OR (("Hatred_1"."Keyword" >= 'fatass') AND ("Hatred_1"."Keyword" <= 'injun')) OR (("Hatred_1"."Keyword" >= 'nigger') AND ("Hatred_1"."Keyword" <= 'papist')) OR (("Hatred_1"."Keyword" >= 'rag head') AND ("Hatred_1"."Keyword" <= 'sandnigger')) OR (("Hatred_1"."Keyword" >= 'shemale') AND ("Hatred_1"."Keyword" <= 'spic')) OR (("Hatred_1"."Keyword" >= 'towel head') AND ("Hatred_1"."Keyword" <= 'tranny'))) GROUP BY "Hatred_1"."Keyword",   "Hatred_1"."State_" HAVING ((SUM(1) >= 30) AND (SUM(1) <= 100000));
